.perm{position:relative;width:100%;aspect-ratio:720/1000;container-type:size;overflow:hidden;border-radius:12px;background:#000;font-family:"PingFang SC","Microsoft YaHei",sans-serif;user-select:none;-webkit-user-select:none}
.perm *,.perm *::before,.perm *::after{box-sizing:border-box}
.perm button{font-family:inherit;cursor:pointer}
.perm-wall{position:absolute;inset:0;background:linear-gradient(165deg,#0f1428,#141c3c 45%,#1a1230);transition:filter .6s}
[data-os="ios"] .perm-wall{background:linear-gradient(165deg,#e9eef4,#cfd9e6 55%,#b9c6da)}
[data-os="win"] .perm-wall{background:linear-gradient(150deg,#0a2f52,#0d3f6e 50%,#07223d)}
.perm.done .perm-wall{filter:brightness(.5) saturate(.55)}
.perm-home{position:absolute;left:9cqw;right:9cqw;top:13cqh;display:grid;grid-template-columns:repeat(4,1fr);gap:4cqh 5cqw;filter:blur(1px);opacity:.5;transition:opacity .6s}
.perm.done .perm-home{opacity:.14}
.perm-home i{aspect-ratio:1;border-radius:26%;display:block}
.perm-home i:nth-child(1){background:linear-gradient(135deg,#5b8def,#8fb4ff)}
.perm-home i:nth-child(2){background:linear-gradient(135deg,#ef8f5b,#ffd0a8)}
.perm-home i:nth-child(3){background:linear-gradient(135deg,#5bc48f,#a8ffd0)}
.perm-home i:nth-child(4){background:linear-gradient(135deg,#c45bef,#f0a8ff)}
.perm-home i:nth-child(5){background:linear-gradient(135deg,#ef5b5b,#ffb0a8)}
.perm-home i:nth-child(6){background:linear-gradient(135deg,#5bc4ef,#a8e4ff)}
.perm-home i:nth-child(7){background:linear-gradient(135deg,#efc45b,#fff0a8)}
.perm-home i:nth-child(8){background:linear-gradient(135deg,#8f8fa8,#c9c9de)}
.perm-home i:nth-child(9){background:linear-gradient(135deg,#4a6ea8,#7ba6dd)}
.perm-home i:nth-child(10){background:linear-gradient(135deg,#a85b7a,#e0a8c0)}
.perm-home i:nth-child(11){background:linear-gradient(135deg,#5ba87a,#a8e0c0)}
.perm-home i:nth-child(12){background:linear-gradient(135deg,#a88f5b,#e0d0a8)}
[data-os="win"] .perm-home{display:none}
.perm-status{position:absolute;top:0;left:0;right:0;height:5.6cqh;display:flex;align-items:center;justify-content:space-between;padding:0 4.4cqw;color:#fff;font-size:2cqh;z-index:6;letter-spacing:.1cqh}
[data-os="ios"] .perm-status{color:#1c1c1e;font-weight:600}
[data-os="win"] .perm-status{top:auto;bottom:0;height:6.4cqh;background:rgba(16,26,40,.92);justify-content:flex-end;font-size:2cqh;letter-spacing:.05cqh}
.perm-si{display:flex;gap:.5cqw;align-items:center}
.perm-si .b1,.perm-si .b2,.perm-si .b3,.perm-si .b4{width:.95cqw;background:currentColor;border-radius:1px;display:block}
.perm-si .b1{height:1.1cqh}
.perm-si .b2{height:1.5cqh}
.perm-si .b3{height:1.9cqh}
.perm-si .b4{height:2.3cqh}
.perm-batt{width:4.8cqw;height:2.4cqh;border:1px solid currentColor;border-radius:.6cqh;position:relative;display:block}
.perm-batt::before{content:"";position:absolute;right:-1.5cqw;top:28%;bottom:28%;width:1.1cqw;background:currentColor;border-radius:1px}
.perm-batt::after{content:"";position:absolute;left:.35cqw;top:.35cqh;bottom:.35cqh;width:72%;background:currentColor;border-radius:.35cqh}
.perm-toast{position:absolute;left:50%;bottom:10cqh;transform:translate(-50%,2cqh);background:rgba(18,20,26,.93);color:#eee;font-size:2cqh;padding:1.5cqh 3.6cqw;border-radius:999px;opacity:0;pointer-events:none;transition:opacity .25s,transform .25s;z-index:9;max-width:88%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.perm-toast.on{opacity:1;transform:translate(-50%,0)}
.perm-dim{position:absolute;inset:0;background:rgba(0,0,0,.42);opacity:0;transition:opacity .25s;z-index:7;pointer-events:none}
.perm-dim.on{opacity:1}
.perm-dlg{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%) scale(.92);width:82cqw;background:#fff;color:#111;border-radius:3cqh;box-shadow:0 4cqh 12cqh rgba(0,0,0,.38);opacity:0;z-index:8;pointer-events:none;transition:opacity .18s,transform .18s}
.perm-dlg.pop{opacity:1;transform:translate(-50%,-50%) scale(1);pointer-events:auto}
.perm-dlg.out{opacity:0;transform:translate(-50%,-52%) scale(.95)}
.perm-dlg.shake{animation:pShake .5s ease}
@keyframes pShake{0%,100%{transform:translate(-50%,-50%) scale(1)}20%{transform:translate(calc(-50% - 1.1cqw),-50%) scale(1)}40%{transform:translate(calc(-50% + 1.1cqw),-50%) scale(1)}60%{transform:translate(calc(-50% - .6cqw),-50%) scale(1)}80%{transform:translate(calc(-50% + .6cqw),-50%) scale(1)}}
.dlg-in{padding:3cqh 5cqw 0}
.dlg-app{display:flex;align-items:center;gap:2cqw;font-size:2.1cqh;color:#666;margin-bottom:1.6cqh}
.dlg-appic{width:3.8cqh;height:3.8cqh;border-radius:30%;background:linear-gradient(135deg,#3b7bd4,#75a7f0);box-shadow:inset 0 0 0 1px rgba(0,0,0,.08);flex:0 0 auto}
[data-os="ios"] .dlg-app{display:none}
.dlg-ic{display:flex;justify-content:center;align-items:flex-end;height:8.4cqh;margin-bottom:1cqh;color:#3a3a3c}
.dlg-ic svg{width:7.4cqh;height:7.4cqh}
[data-os="win"] .dlg-ic{color:#4cc2ff}
.dlg-title{font-size:2.9cqh;font-weight:600;text-align:center;line-height:1.5;padding:0 1cqw;word-break:break-word}
.dlg-text{font-size:2.1cqh;color:#555;text-align:center;line-height:1.65;padding:1.6cqh 2cqw 2.8cqh;word-break:break-word}
.dlg-btns{display:flex;border-top:1px solid rgba(0,0,0,.12)}
.dlg-btns button{flex:1;height:7.6cqh;font-size:2.7cqh;border:0;background:none;color:#007aff;font-weight:600}
.dlg-btns button.deny{color:#3a3a3c;border-right:1px solid rgba(0,0,0,.12);transition:color .2s,font-size .2s}
.dlg-btns button.deny.weak{color:#c2c2c8;font-size:2.1cqh}
.dlg-btns button:active{background:rgba(0,0,0,.05)}
[data-os="android"] .perm-dlg{border-radius:2.6cqh}
[data-os="android"] .dlg-in{padding:3.2cqh 6cqw 0}
[data-os="android"] .dlg-title{text-align:left;font-weight:700}
[data-os="android"] .dlg-text{text-align:left;color:#666}
[data-os="android"] .dlg-app{display:none}
[data-os="android"] .dlg-ic{justify-content:flex-start;height:7.4cqh}
[data-os="android"] .dlg-btns{border-top:0;justify-content:flex-end;padding:0 3cqw 1.6cqh}
[data-os="android"] .dlg-btns button{flex:0 0 auto;width:19cqw;height:5.8cqh;font-size:2.3cqh;color:#1a73e8;border-radius:.9cqh}
[data-os="android"] .dlg-btns button.deny{color:#757575;border-right:0}
[data-os="win"] .perm-dlg{background:#2b2b2b;color:#f0f0f0;border-radius:1.8cqh;box-shadow:0 3cqh 10cqh rgba(0,0,0,.55)}
[data-os="win"] .dlg-in{padding:3cqh 5.4cqw 0}
[data-os="win"] .dlg-app{color:#9a9a9a}
[data-os="win"] .dlg-title{text-align:left;font-weight:600}
[data-os="win"] .dlg-text{text-align:left;color:#bcbcbc}
[data-os="win"] .dlg-btns{border-top:1px solid #3f3f3f;justify-content:flex-end;padding:1.6cqh 3cqw 2cqh}
[data-os="win"] .dlg-btns button{flex:0 0 auto;width:20cqw;height:5.8cqh;font-size:2.2cqh;border-radius:.9cqh;background:#404040;color:#f0f0f0;font-weight:400}
[data-os="win"] .dlg-btns button.deny{border-right:0}
[data-os="win"] .dlg-btns button.allow{background:#4cc2ff;color:#0b0b0b;font-weight:600}
.perm-set{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:86cqw;background:#14161c;color:#eee;border-radius:2.6cqh;z-index:8;opacity:0;pointer-events:none;transition:opacity .35s;box-shadow:0 4cqh 14cqh rgba(0,0,0,.6)}
.perm-set.on{opacity:1}
.set-head{font-size:3cqh;font-weight:700;text-align:center;padding:3.2cqh 0 1cqh}
.set-sub{font-size:2cqh;color:#8a8f9c;text-align:center;padding:0 4cqw 2.4cqh}
.perm-set ul{list-style:none;margin:0;padding:0;border-top:1px solid #262a34}
.perm-set li{display:flex;align-items:center;justify-content:space-between;gap:2cqw;padding:2.2cqh 5cqw;border-bottom:1px solid #262a34;font-size:2.3cqh;opacity:0;animation:pRow .5s ease forwards}
.perm-set li:nth-child(1){animation-delay:.25s}
.perm-set li:nth-child(2){animation-delay:.6s}
.perm-set li:nth-child(3){animation-delay:.95s}
.perm-set li:nth-child(4){animation-delay:1.7s}
.perm-set li b{font-size:1.9cqh;color:#37c26e;font-weight:600;white-space:nowrap}
.perm-set li.warn{color:#ff5566}
.perm-set li.warn b{color:#ff5566}
@keyframes pRow{from{opacity:0;transform:translateX(3cqw)}to{opacity:1;transform:none}}
.set-end{font-size:2cqh;color:#9aa0ad;text-align:center;line-height:1.7;padding:2.6cqh 5cqw 3.4cqh;opacity:0;animation:pRow .8s ease 2.5s forwards;margin:0;word-break:break-word}
.perm.glitch{animation:pGlitch .42s steps(2) both}
@keyframes pGlitch{0%{filter:none}30%{filter:invert(1) hue-rotate(90deg)}55%{filter:none}80%{filter:invert(1)}100%{filter:none}}
.perm-data{display:none}

