"use strict";
(function(){
function G(i){return document.getElementById(i)}
function raw(i){var e=G(i);return e?String(e.textContent||""):""}
function ok(s){s=String(s||"").trim();if(!s){return false}for(var i=0;i<s.length;i++){if(s.charCodeAt(i)===36){return false}}return true}
var SRC=ok(raw("pSrc"))?raw("pSrc").trim():"系统服务";
var END=ok(raw("pEnd"))?raw("pEnd").trim():"其实我不需要这些权限。看到你按下『允许』的样子，就已经够了。";
var root=G("permRoot");
var ua=navigator.userAgent||"";
var os="win";
if(ua.indexOf("Android")>=0){os="android"}
else if(ua.indexOf("iPhone")>=0||ua.indexOf("iPad")>=0||ua.indexOf("iPod")>=0){os="ios"}
root.setAttribute("data-os",os);
G("dlgAppName").textContent=SRC;
G("setAppName").textContent=SRC;
G("setEnd").textContent=END;
function clock(){var d=new Date(),h=d.getHours(),m=d.getMinutes();G("permClock").textContent=(h<10?"0":"")+h+":"+(m<10?"0":"")+m}
clock();setInterval(clock,20000);
function vib(p){try{if(navigator.vibrate){navigator.vibrate(p)}}catch(e){}}
var actx=null;
function ding(){try{var AC=window.AudioContext||window.webkitAudioContext;if(!AC){return}if(!actx){actx=new AC()}if(actx.state==="suspended"){actx.resume()}var o=actx.createOscillator(),g=actx.createGain(),t=actx.currentTime;o.type="sine";o.frequency.value=920;g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(0.22,t+0.02);g.gain.exponentialRampToValueAtTime(0.0001,t+0.4);o.connect(g);g.connect(actx.destination);o.start(t);o.stop(t+0.45)}catch(e){}}
var GL="▓▒░█▄▀◤◢";
function gl(s,p){var r="",i,c;for(i=0;i<s.length;i++){c=s.charAt(i);r+=(c!==" "&&c!=="，"&&c!=="。"&&Math.random()<p)?GL.charAt(Math.floor(Math.random()*GL.length)):c}return r}
var A="『"+SRC+"』";
var T={ios:[[A+"想访问您的相机","允许"+A+"在您使用应用时拍摄照片和录制视频"],[A+"想访问您的麦克风","允许"+A+"在您使用应用时录音"],[A+"想访问您的位置","允许"+A+"在您使用应用时获取您的位置信息"]],android:[["是否允许"+A+"拍摄照片和录制视频？","应用可能在后台使用相机，拒绝可能导致部分功能异常。"],["是否允许"+A+"录音？","应用可能在后台使用麦克风。"],["是否允许"+A+"获取此设备的位置信息？","位置信息属于敏感个人数据。"]],win:[["是否允许"+A+"使用摄像头？","Windows 安全中心检测到"+A+"正在尝试访问你的摄像头。"],["是否允许"+A+"使用麦克风？","Windows 安全中心检测到"+A+"正在尝试访问你的麦克风。"],["是否允许"+A+"访问你的位置？","Windows 安全中心检测到"+A+"正在尝试访问你的位置信息。"]]};
var NAMES=["相机","麦克风","位置"];
var ICONS=["icCam","icMic","icLoc"];
var DENYMAX=[2,1,0];
var DENYLBL={ios:"不允许",android:"不允许",win:"阻止"};
var cur=0,att=0,phase="idle",cdt=null;
function toast(s,d){var t=G("permToast");t.textContent=s;t.className="perm-toast on";setTimeout(function(){t.className="perm-toast"},d||1800)}
function openDlg(){
phase=(att>=DENYMAX[cur])?"count":"ask";
var row=T[os][cur],k=Math.min(att,2);
var dlg=G("permDlg");
G("dlgTitle").textContent=att>0?gl(row[0],0.04+0.05*k):row[0];
G("dlgText").textContent=att>0?gl(row[1],0.06+0.08*k):row[1];
var i,ic;
for(i=0;i<3;i++){ic=G(ICONS[i]);ic.style.display=(i===cur)?"":"none"}
var dn=G("pDeny");
dn.style.display=(att<DENYMAX[cur])?"":"none";
dn.className="deny"+(att>0?" weak":"");
dn.textContent=DENYLBL[os];
G("pAllow").textContent="允许";
G("permDim").className="perm-dim on";
dlg.className="perm-dlg";
void dlg.offsetWidth;
dlg.className="perm-dlg pop"+(phase==="count"?" shake":"");
ding();vib(phase==="count"?[60,50,60]:30);
if(phase==="count"){
var n=3;
G("pAllow").textContent="允许（"+n+"）";
cdt=setInterval(function(){n--;if(n<=0){clearInterval(cdt);cdt=null;doAllow()}else{G("pAllow").textContent="允许（"+n+"）"}},750)
}}
function closeDlg(){G("permDlg").className="perm-dlg out";setTimeout(function(){G("permDlg").className="perm-dlg"},280)}
function doAllow(){
if(phase!=="ask"&&phase!=="count"){return}
if(cdt){clearInterval(cdt);cdt=null}
phase="grant";
toast("已允许"+A+"使用"+NAMES[cur]);
closeDlg();
cur+=1;
if(cur>=3){setTimeout(finale,1000)}
else{att=0;setTimeout(openDlg,1200)}
}
function doDeny(){
if(phase!=="ask"){return}
phase="deny";
att+=1;
toast("权限请求被拒绝");
closeDlg();
setTimeout(openDlg,att>=DENYMAX[cur]?450:850)
