function finale(){
root.className="perm glitch";
vib([80,60,140]);
setTimeout(function(){root.className="perm done"},430);
setTimeout(function(){
G("permDlg").className="perm-dlg";
G("permSet").className="perm-set on";
ding();setTimeout(ding,280);setTimeout(ding,620)
},440)
}
setTimeout(function(){toast("正在进行设备安全验证…",1600)},600);
